import json, os, shutil, subprocess
from pathlib import Path

tmp_dir = Path("/work/build-baseline/tmp")
if tmp_dir.exists():
    # Ensure user-owned subdirs with restrictive modes (like archiver-work) are writable before rmtree
    for r, dirs, files in os.walk(tmp_dir):
        for d in dirs:
            p = Path(r) / d
            if not p.is_symlink():
                try:
                    p.chmod(0o700)
                except OSError:
                    pass
    shutil.rmtree(tmp_dir)

removed_target_sstate = 0
for r, dirs, files in os.walk("/work/sstate-cache"):
    for f in files:
        fl = f.lower()
        if any(tok in fl for tok in ("libwebsockets", "firmdura-lws-h2-tests", "firmdura-reference-image")):
            (Path(r) / f).unlink()
            removed_target_sstate += 1

rem = subprocess.check_output([
    "find", "/work/sstate-cache",
    "(", "-iname", "*libwebsockets*", "-o", "-iname", "*firmdura-lws-h2-tests*", "-o", "-iname", "*firmdura-reference-image*", ")"
], text=True).strip()
assert rem == "", f"Target sstate still present: {rem}"
df_out = subprocess.check_output(["df", "-h", "/work"], text=True).strip()
print(json.dumps({"baseline_tmp_removed": not tmp_dir.exists(), "removed_target_sstate_files": removed_target_sstate, "remaining_target_sstate": 0, "df_h": df_out}, indent=2))

